m2_content = '''"""Tests for milestone m2: Add .memory and .skip to cache wrapper, unified with memoize."""


def test_cache_has_memory():
    from funcy import cache

    @cache(30)
    def f(x):
        return x * 2

    result = f(5)
    assert result == 10
    assert hasattr(f, "memory")
    assert isinstance(f.memory, dict)
    assert (5,) in f.memory
    # memory value should be a tuple of (result, datetime)
    val = f.memory[(5,)]
    assert isinstance(val, tuple)
    assert len(val) == 2
    assert val[0] == 10


def test_cache_skip_is_same_as_memoize_skip():
    from funcy import cache, memoize, SkipMemoization

    @cache(30)
    def cf(x):
        return x * 2

    @memoize
    def mf(x):
        return x * 2

    assert hasattr(cf, "skip")
    assert hasattr(mf, "skip")
    assert cf.skip is mf.skip
    assert cf.skip is SkipMemoization


def test_cache_invalidate_still_works():
    from funcy import cache

    @cache(30)
    def f(x):
        return x * 2

    f(5)
    assert (5,) in f.memory
    f.invalidate(5)
    assert (5,) not in f.memory


def test_cache_invalidate_all_still_works():
    from funcy import cache

